enum WeaponCategory_t
{
    WEAPON_CATEGORY_KNIFE = 0,
    WEAPON_CATEGORY_PISTOL,
    WEAPON_CATEGORY_SMG,
    WEAPON_CATEGORY_RIFLE,
    WEAPON_CATEGORY_SHOTGUN,
    WEAPON_CATEGORY_SNIPER,
    WEAPON_CATEGORY_MACHINEGUN,
    WEAPON_CATEGORY_EQUIPMENT,
    WEAPON_CATEGORY_GRENADE,
    WEAPON_CATEGORY_UNKNOWN,
    WEAPON_CATEGORY_COUNT
};

const char* GetWeaponCategoryName(WeaponCategory_t cat)
{
    static const char* names[] = {
        "weapon_category_knife",
        "weapon_category_pistol",
        "weapon_category_smg",
        "weapon_category_rifle",
        "weapon_category_shotgun",
        "weapon_category_sniper",
        "weapon_category_machinegun",
        "weapon_category_equipment",
        "weapon_category_grenade",
        "weapon_category_unknown"
    };
    if (cat >= 0 && cat < WEAPON_CATEGORY_COUNT)
        return names[cat];
    return "weapon_category_unknown";
}

